function fmtDate(d: Date | string | null | undefined) {
  if (!d) return "";
  return new Date(d).toLocaleDateString("ar-SA");
}

// ── Actions router by dept ──────────────────────────────────────────
type DeptKey = "STRATEGY" | "GOVERNANCE" | "FINANCE" | "SERVICE";

async function actionSetCurrent(dept: DeptKey, serviceId: string, charityId: string, stageId: string) {
  if (dept === "STRATEGY") return setCurrentStrategicStage(charityId, stageId);
  if (dept === "GOVERNANCE") return setCurrentGovernanceStage(charityId, stageId);
  if (dept === "FINANCE") return setCurrentFinanceStage(charityId, stageId);
  return setCurrentServiceStage(serviceId, stageId);
}
async function actionToggleCurrent(dept: DeptKey, stageId: string, isCurrent: boolean) {
  if (dept === "STRATEGY") return toggleCurrentStrategicStage(stageId, isCurrent);
  if (dept === "GOVERNANCE") return toggleCurrentGovernanceStage(stageId, isCurrent);
  if (dept === "FINANCE") return toggleCurrentFinanceStage(stageId, isCurrent);
  return toggleCurrentServiceStage(stageId, isCurrent);
}
async function actionAdd(dept: DeptKey, serviceId: string, charityId: string, name: string, desc: string | null, start: Date | null, end: Date | null, isContinuous = false) {
  if (dept === "STRATEGY") return addStrategicStage(charityId, name, undefined, desc || undefined, start?.toISOString().split("T")[0], end?.toISOString().split("T")[0], isContinuous);
  if (dept === "GOVERNANCE") return addGovernanceStage(charityId, name, undefined, desc || undefined, start?.toISOString().split("T")[0], end?.toISOString().split("T")[0], isContinuous);
  if (dept === "FINANCE") return addFinanceStage(charityId, name, undefined, desc || undefined, start?.toISOString().split("T")[0], end?.toISOString().split("T")[0], isContinuous);
  return addServiceStage(serviceId, name, desc, start, end, isContinuous);
}
async function actionUpdate(dept: DeptKey, stageId: string, name: string, desc: string | null, start: Date | null, end: Date | null, isContinuous = false, duration?: string, isComingSoon: boolean = false) {
  if (dept === "STRATEGY") return updateStrategicStage(stageId, name, undefined, desc || undefined, start?.toISOString().split("T")[0], end?.toISOString().split("T")[0], isContinuous, true, isComingSoon);
  if (dept === "GOVERNANCE") return updateGovernanceStage(stageId, name, undefined, desc || undefined, start?.toISOString().split("T")[0], end?.toISOString().split("T")[0], isContinuous, true, isComingSoon);
  if (dept === "FINANCE") return updateFinanceStage(stageId, name, undefined, desc || undefined, start?.toISOString().split("T")[0], end?.toISOString().split("T")[0], isContinuous, true, isComingSoon);
  return updateServiceStage(stageId, name, desc, start, end, isContinuous, true, duration ?? null, isComingSoon);
}
async function actionDelete(dept: DeptKey, stageId: string) {
  if (dept === "STRATEGY") return deleteStrategicStage(stageId);
  if (dept === "GOVERNANCE") return deleteGovernanceStage(stageId);
  if (dept === "FINANCE") return deleteFinanceStage(stageId);
  return deleteServiceStage(stageId);
}
async function actionReorder(dept: DeptKey, serviceId: string, charityId: string, ids: string[]) {
  if (dept === "STRATEGY") return reorderStrategicStages(charityId, ids);
  if (dept === "GOVERNANCE") return reorderGovernanceStages(charityId, ids);
  if (dept === "FINANCE") return reorderFinanceStages(charityId, ids);
  return reorderServiceStages(ids);
}
async function actionToggleActive(dept: DeptKey, stageId: string, isActive: boolean) {
  if (dept === "STRATEGY") return toggleActiveStrategicStage(stageId, isActive);
  if (dept === "GOVERNANCE") return toggleActiveGovernanceStage(stageId, isActive);
  if (dept === "FINANCE") return toggleActiveFinanceStage(stageId, isActive);
  return toggleActiveServiceStage(stageId, isActive);
}

// ── Date calculation helpers ────────────────────────────────────────
function addDays(date: Date, days: number, workOnly: boolean): Date {
  const d = new Date(date);
  let added = 0;
  while (added < days) {
    d.setDate(d.getDate() + 1);
    if (!workOnly || (d.getDay() !== 5 && d.getDay() !== 6)) added++;
  }
  return d;
}

function toDateInput(d: Date): string {
  return d.toISOString().split("T")[0];
}

function calcDatesFromDays(
  days: number,
  workOnly: boolean,
  prevEndDate: Date | string | null | undefined
): { start: string; end: string } {
  const startBase = prevEndDate ? new Date(prevEndDate) : new Date();
  // start = day after prev end (or today)
  const start = prevEndDate ? addDays(startBase, 1, false) : startBase;
  // normalize to midnight
  start.setHours(0, 0, 0, 0);
  const end = addDays(new Date(start), days - 1, workOnly);
  return { start: toDateInput(start), end: toDateInput(end) };
}

// ── Inline Timeline Editor ──────────────────────────────────────────
function InlineTimeline({
  stages: initialStages,
  charityId,
  serviceId,
  dept,
  canEdit,
  onUnifyClick,
}: {
  stages: Stage[];
  charityId: string;
  serviceId: string;
  dept: DeptKey;
  canEdit: boolean;
  onUnifyClick?: () => void;
}) {
  const [stages, setStages] = useState<Stage[]>(initialStages);
  const router = useRouter();

  const [isEditing, setIsEditing] = useState(false);
  const [isPending, startTransition] = useTransition();
  const [showAllStages, setShowAllStages] = useState(false);

  const sorted = [...stages].sort((a, b) => a.order - b.order);
  const currentIdx = sorted.findIndex(s => s.isCurrent);
  const total = sorted.length;

  // Edit state
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState("");
  const [editDesc, setEditDesc] = useState("");
  const [editStart, setEditStart] = useState("");
  const [editEnd, setEditEnd] = useState("");
  const [isAdding, setIsAdding] = useState(false);
  const [newName, setNewName] = useState("");
  const [newDesc, setNewDesc] = useState("");
  const [newStart, setNewStart] = useState("");
  const [newEnd, setNewEnd] = useState("");
  const [newIsContinuous, setNewIsContinuous] = useState(false);
  const [editIsContinuous, setEditIsContinuous] = useState(false);
  const [editIsComingSoon, setEditIsComingSoon] = useState(false);

  // Days-based duration
  const [editDays, setEditDays] = useState("");
  const [editWorkDaysOnly, setEditWorkDaysOnly] = useState(false);
  const [newDays, setNewDays] = useState("");
  const [newWorkDaysOnly, setNewWorkDaysOnly] = useState(false);

  const openEdit = (s: Stage) => {
    setEditingId(s.id);
    setEditName(s.name);
    setEditDesc(s.description || "");
    setEditStart(s.startDate ? new Date(s.startDate).toISOString().split("T")[0] : "");
    setEditEnd(s.endDate ? new Date(s.endDate).toISOString().split("T")[0] : "");
    setEditIsContinuous(!!s.isContinuous);
    setEditIsComingSoon(!!s.isComingSoon);
    setEditDays("");
    setEditWorkDaysOnly(false);
  };

  const handleToggleCurrent = (stageId: string) => {
    startTransition(async () => {
      const sorted = [...stages].sort((a, b) => a.order - b.order).filter(s => !s.isContinuous);
      const clickedIdx = sorted.findIndex(s => s.id === stageId);
      const wasActive = sorted[clickedIdx]?.isCurrent;
      
      const newVal = !wasActive;

      // تحديث واجهة المستخدم فورياً لتتطابق مع الآلية الجديدة في السيرفر
      setStages(prev => prev.map(s => {
        if (s.isContinuous) return s;
        const idx = sorted.findIndex(r => r.id === s.id);
        if (newVal) {
          if (idx < clickedIdx) {
            return { 
              ...s, 
              isCurrent: false, 
              isDone: true, 
              steps: s.steps ? s.steps.map(step => ({ ...step, isDone: true })) : [] 
            };
          }
          if (idx === clickedIdx) {
            return { 
              ...s, 
              isCurrent: true,
              isDone: false,
              steps: s.steps ? s.steps.map(step => ({ ...step, isDone: false })) : [] 
            };
          }
          return { 
            ...s, 
            isCurrent: false,
            isDone: false,
            steps: s.steps ? s.steps.map(step => ({ ...step, isDone: false })) : [] 
          };
        } else {
          if (idx === clickedIdx) return { ...s, isCurrent: false };
          return s;
        }
      }));

      if (newVal) {
        await actionSetCurrent(dept, serviceId, charityId, stageId);
      } else {
        await actionToggleCurrent(dept, stageId, false);
      }
      router.refresh();
    });
  };

  const handleUpdate = (id: string) => {
    if (!editName.trim()) return;
    startTransition(async () => {
      let start: Date | null = editStart ? new Date(editStart) : null;
      let end: Date | null = editEnd ? new Date(editEnd) : null;
      let durStr: string | null = null;

      if (editDays && parseInt(editDays) > 0) {
        const idx = sorted.findIndex(s => s.id === id);
        const prevEnd = idx > 0 ? sorted[idx - 1].endDate : null;
        const calc = calcDatesFromDays(parseInt(editDays), editWorkDaysOnly, prevEnd);
        start = new Date(calc.start);
        end = new Date(calc.end);
        durStr = editWorkDaysOnly ? `${editDays}w` : `${editDays}d`;
      }

      setStages(prev => prev.map(s => s.id === id
        ? { ...s, name: editName, description: editDesc || null, startDate: start, endDate: end, isContinuous: editIsContinuous, isComingSoon: editIsComingSoon, duration: durStr ?? s.duration }
        : s));
      setEditingId(null);
      await actionUpdate(dept, id, editName, editDesc || null, start, end, editIsContinuous, durStr ?? undefined, editIsComingSoon);
      router.refresh();
    });
  };

  const handleToggleStepOptimistic = (targetStageId: string, targetStepId: string, isDone: boolean) => {
    setStages(prev => {
      const sorted = [...prev].sort((a, b) => a.order - b.order).filter(s => !s.isContinuous);
      const targetStageIndex = sorted.findIndex(s => s.id === targetStageId);
      if (targetStageIndex === -1) return prev;
      
      const targetStage = sorted[targetStageIndex];
      const sortedSteps = [...(targetStage.steps || [])].sort((a, b) => a.order - b.order);
      const targetStepIndex = sortedSteps.findIndex(stp => stp.id === targetStepId);
      if (targetStepIndex === -1) return prev;

      // 1. تحديث الإنجاز بناءً على المنطق المائي (Water-mark)
      const updatedStages = prev.map(s => {
        if (s.isContinuous) return s;
        const stageIdx = sorted.findIndex(r => r.id === s.id);
        
        let newIsDone = s.isDone;
        let newSteps = s.steps ? [...s.steps] : [];

        if (isDone) {
          if (stageIdx < targetStageIndex) {
            newIsDone = true;
            newSteps = newSteps.map(step => ({ ...step, isDone: true }));
          } else if (stageIdx === targetStageIndex) {
            newSteps = newSteps.map(step => {
               const stepIdx = sortedSteps.findIndex(x => x.id === step.id);
               return { ...step, isDone: stepIdx <= targetStepIndex };
            });
          } else {
            newIsDone = false;
            newSteps = newSteps.map(step => ({ ...step, isDone: false }));
          }
        } else {
          if (stageIdx === targetStageIndex) {
            newSteps = newSteps.map(step => {
               const stepIdx = sortedSteps.findIndex(x => x.id === step.id);
               return { ...step, isDone: stepIdx < targetStepIndex ? step.isDone : false };
            });
          } else if (stageIdx > targetStageIndex) {
            newIsDone = false;
            newSteps = newSteps.map(step => ({ ...step, isDone: false }));
          }
        }
        
        return { ...s, isDone: newIsDone, steps: newSteps, isCurrent: false };
      });

      // 2. إعادة حساب المرحلة الحالية وإنجازها
      const regularUpdated = updatedStages.filter(s => !s.isContinuous).sort((a, b) => a.order - b.order);
      
      regularUpdated.forEach(s => {
        if (s.steps && s.steps.length > 0) {
          s.isDone = s.steps.every(stp => stp.isDone);
        }
      });

      let currentIdx = regularUpdated.findIndex(s => !s.isDone);
      if (currentIdx === -1) currentIdx = regularUpdated.length - 1;

      return updatedStages.map(s => {
        if (s.isContinuous) return s;
        const rIdx = regularUpdated.findIndex(r => r.id === s.id);
        return { ...s, isCurrent: rIdx === currentIdx, isDone: regularUpdated[rIdx].isDone };
      });
    });
  };

  const handleDelete = (id: string) => {
    if (!confirm("حذف هذه المرحلة؟")) return;
    startTransition(async () => {
      setStages(prev => prev.filter(s => s.id !== id));
      await actionDelete(dept, id);
    });
  };

  const handleAdd = () => {
    if (!newName.trim()) return;
    startTransition(async () => {
      let start: Date | null = newStart ? new Date(newStart) : null;
      let end: Date | null = newEnd ? new Date(newEnd) : null;
      let durStr: string | null = null;

      if (newDays && parseInt(newDays) > 0) {
        const regularSorted = sorted.filter(s => !s.isContinuous);
        const prevEnd = regularSorted.length > 0 ? regularSorted[regularSorted.length - 1].endDate : null;
        const calc = calcDatesFromDays(parseInt(newDays), newWorkDaysOnly, prevEnd);
        start = new Date(calc.start);
        end = new Date(calc.end);
        durStr = newWorkDaysOnly ? `${newDays}w` : `${newDays}d`;
      }

      await actionAdd(dept, serviceId, charityId, newName, newDesc || null, start, end, newIsContinuous);
      const newStage: Stage = {
        id: Math.random().toString(),
        charityId,
        name: newName,
        description: newDesc || null,
        startDate: start,
        endDate: end,
        order: stages.length,
        isCurrent: false,
        isContinuous: newIsContinuous,
        duration: durStr,
      };
      setStages(prev => [...prev, newStage]);
      setNewName(""); setNewDesc(""); setNewStart(""); setNewEnd("");
      setNewDays(""); setNewWorkDaysOnly(false); setNewIsContinuous(false);
      setIsAdding(false);
    });
  };

  const handleMove = (idx: number, dir: "up" | "down") => {
    const newSorted = [...sorted];
    const target = dir === "up" ? idx - 1 : idx + 1;
    if (target < 0 || target >= newSorted.length) return;
    [newSorted[idx], newSorted[target]] = [newSorted[target], newSorted[idx]];
    // Recalculate dates for stages that have duration (days) stored
    const reordered = newSorted.map((s, i) => {
      if (!s.duration) return { ...s, order: i };
      const days = parseInt(s.duration);
      if (!days || isNaN(days)) return { ...s, order: i };
      const workOnly = s.duration.includes("w");
      const prevEnd = i > 0 ? newSorted[i - 1].endDate : null;
      const { start, end } = calcDatesFromDays(days, workOnly, prevEnd);
      return { ...s, order: i, startDate: new Date(start), endDate: new Date(end) };
    });
    setStages(reordered);
    startTransition(async () => {
      await actionReorder(dept, serviceId, charityId, reordered.map(s => s.id));
      // Update dates for stages with recalculated dates
      for (const s of reordered) {
        if (s.duration && parseInt(s.duration)) {
          await actionUpdate(dept, s.id, s.name, s.description ?? null, s.startDate ? new Date(s.startDate) : null, s.endDate ? new Date(s.endDate) : null, !!s.isContinuous);
        }
      }
    });
  };

  const listRef = useRef<HTMLDivElement>(null);

  // VIEW MODE
  if (!isEditing) {
    const continuousStages = sorted.filter(s => s.isContinuous);
    const regularStages = sorted.filter(s => !s.isContinuous);
    // آخر مرحلة حالية في الترتيب — كل ما قبلها يُعدّ منجزاً
    const lastCurrentIdx = regularStages.reduce((last, s, i) => s.isCurrent ? i : last, -1);

    // عرض 5 مراحل فقط مع إمكانية عرض الكل
    const MAX_VISIBLE = 5;

    // حساب نافذة الـ5 مراحل المرئية بحيث تشمل المرحلة الحالية
    const getVisibleRegularStages = () => {
      if (showAllStages || regularStages.length <= MAX_VISIBLE) return regularStages;
      if (lastCurrentIdx === -1) return regularStages.slice(0, MAX_VISIBLE);
      // ابدأ من المرحلة الحالية مع وضعها في الأول
      const start = Math.max(0, Math.min(lastCurrentIdx, regularStages.length - MAX_VISIBLE));
      return regularStages.slice(start, start + MAX_VISIBLE);
    };
    const visibleRegularStages = getVisibleRegularStages();
    const hasHiddenStages = !showAllStages && regularStages.length > MAX_VISIBLE;
    // الأوفست لأرقام المراحل
    const visibleOffset = showAllStages || regularStages.length <= MAX_VISIBLE ? 0
      : Math.max(0, Math.min(lastCurrentIdx, regularStages.length - MAX_VISIBLE));

    return (
      <div className="mt-2">
        {total === 0 && <p className="text-xs text-slate-400 italic py-2">لا توجد مراحل مسجلة</p>}

        {total > 0 && (
          <div
            ref={listRef}
            className="space-y-1 select-none"
          >
            {/* المراحل الدائمة — خارج الترتيب المرقم، تظهر أولاً */}
            {continuousStages.length > 0 && (
              <div className="mb-2 pb-2 border-b border-dashed border-amber-200 dark:border-amber-800/40 space-y-1">
                {continuousStages.map(stage => {
                  const active = stage.isActive !== false;
                  return (
                  <div key={stage.id} className={`flex items-start gap-2.5 p-2 rounded-lg text-xs border ${active ? "bg-amber-50/60 dark:bg-amber-900/10 border-amber-100 dark:border-amber-800/30" : "bg-slate-50 dark:bg-slate-800/30 border-slate-200 dark:border-slate-700/50 opacity-50"}`}>
                    <div className="w-5 h-5 rounded-md flex items-center justify-center shrink-0 mt-0.5 bg-amber-400 dark:bg-amber-600 text-white text-[11px] font-bold">∞</div>
                    <div className="flex-1 min-w-0">
                      <div className={`font-semibold leading-tight flex items-center gap-1.5 flex-wrap ${active ? "text-amber-800 dark:text-amber-300" : "text-slate-500"}`}>
                        {stage.name}
                        <span className="text-[9px] text-amber-600 dark:text-amber-400 font-medium opacity-70">دائمة</span>
                        {stage.isComingSoon && <span className="text-[9px] bg-purple-500 text-white px-1.5 py-0.5 rounded-full font-bold">قريباً</span>}
                      </div>
                      {stage.description && <p className="text-amber-700/70 dark:text-amber-400/60 mt-0.5 text-[11px]">{stage.description}</p>}
                      {(stage.startDate || stage.endDate) && (
                        <div className="flex items-center gap-1 mt-0.5 text-amber-600/60 dark:text-amber-500/50">
                          <Calendar className="w-3 h-3 shrink-0" />
                          <span dir="ltr">{fmtDate(stage.startDate)}{stage.startDate && stage.endDate ? " — " : ""}{fmtDate(stage.endDate)}</span>
                        </div>
                      )}
                    </div>
                    <button
                      onClick={() => {
                        startTransition(async () => {
                          setStages(prev => prev.map(s => s.id === stage.id ? { ...s, isActive: !active } : s));
                          await actionToggleActive(dept, stage.id, !active);
                        });
                      }}
                      disabled={isPending}
                      className={`shrink-0 text-[9px] font-bold px-1.5 py-0.5 rounded transition-colors ${active ? "bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-400 hover:bg-amber-200" : "bg-slate-100 dark:bg-slate-700 text-slate-500 hover:bg-slate-200"}`}
                    >
                      {active ? "تعطيل" : "تفعيل"}
                    </button>
                  </div>
                  );
                })}
              </div>
            )}

            {/* المراحل العادية — الخط المرقم (5 فقط) */}
            {visibleRegularStages.map((stage, localIdx) => {
              const idx = visibleOffset + localIdx;
              const isCompleted = lastCurrentIdx !== -1 && idx < lastCurrentIdx;
              const isCurrent = stage.isCurrent;
              return (
                <div key={stage.id} className={`flex items-start gap-2.5 p-2 rounded-lg text-xs group ${isCurrent ? "bg-primary/8 dark:bg-primary/15" : "hover:bg-slate-50 dark:hover:bg-slate-700/30"}`}>
                  <div className={`w-5 h-5 rounded-full flex items-center justify-center shrink-0 text-[10px] font-bold mt-0.5 border ${
                    isCurrent ? "border-primary bg-primary text-white" :
                    isCompleted ? "border-emerald-500 bg-emerald-500 text-white" :
                    "border-slate-300 dark:border-slate-600 text-slate-400"
                  }`}>
                    {(isCurrent || isCompleted) ? <Check className="w-3 h-3" /> : idx + 1}
                  </div>
                  <div className="flex-1 min-w-0 overflow-hidden">
                    <div className={`font-semibold leading-tight ${isCurrent ? "text-primary" : isCompleted ? "text-slate-500 dark:text-slate-400" : "text-slate-700 dark:text-slate-300"}`}>
                      {stage.name}
                      {isCurrent && <span className="mr-1.5 text-[10px] bg-primary text-white px-1.5 py-0.5 rounded-full font-bold">حالية</span>}
                      {stage.isComingSoon && <span className="mr-1.5 text-[10px] bg-purple-500 text-white px-1.5 py-0.5 rounded-full font-bold">قريباً</span>}
                    </div>
                    {stage.description && <p className="text-slate-500 dark:text-slate-400 mt-0.5 text-[11px] break-words">{stage.description}</p>}
                    {(stage.startDate || stage.endDate) && (
                      <div className="flex items-center gap-1 mt-0.5 text-slate-400 dark:text-slate-500">
                        <Calendar className="w-3 h-3 shrink-0" />
                        <span dir="ltr">{fmtDate(stage.startDate)}{stage.startDate && stage.endDate ? " — " : ""}{fmtDate(stage.endDate)}</span>
                      </div>
                    )}
                    {(stage.steps && stage.steps.length > 0 || canEdit) && (
                      <StageStepsPanel
                        steps={stage.steps || []}
                        canEdit={canEdit}
                        onAdd={(name) => {
                          if (dept === "STRATEGY") return addStrategicStageStep(stage.id, name);
                          if (dept === "GOVERNANCE") return addGovernanceStageStep(stage.id, name);
                          if (dept === "FINANCE") return addFinanceStageStep(stage.id, name);
                          return addServiceStageStep(stage.id, name);
                        }}
                        onToggle={(stepId, isDone) => {
                          handleToggleStepOptimistic(stage.id, stepId, isDone);
                          if (dept === "STRATEGY") return updateStrategicStageStep(stepId, { isDone });
                          if (dept === "GOVERNANCE") return updateGovernanceStageStep(stepId, { isDone });
                          if (dept === "FINANCE") return updateFinanceStageStep(stepId, { isDone });
                          return updateServiceStageStep(stepId, { isDone });
                        }}
                        onRename={(stepId, name) => {
                          if (dept === "STRATEGY") return updateStrategicStageStep(stepId, { name });
                          if (dept === "GOVERNANCE") return updateGovernanceStageStep(stepId, { name });
                          if (dept === "FINANCE") return updateFinanceStageStep(stepId, { name });
                          return updateServiceStageStep(stepId, { name });
                        }}
                        onDelete={(stepId) => {
                          if (dept === "STRATEGY") return deleteStrategicStageStep(stepId);
                          if (dept === "GOVERNANCE") return deleteGovernanceStageStep(stepId);
                          if (dept === "FINANCE") return deleteFinanceStageStep(stepId);
                          return deleteServiceStageStep(stepId);
                        }}
                      />
                    )}
                  </div>
                </div>
              );
            })}

            {/* زر عرض الكل / إخفاء */}
            {regularStages.length > MAX_VISIBLE && (
              <button
                onClick={() => setShowAllStages(v => !v)}
                className="w-full text-center text-[11px] font-bold text-primary/70 hover:text-primary py-1 hover:bg-primary/5 rounded-lg transition-colors"
              >
                {showAllStages ? `إخفاء (${regularStages.length - MAX_VISIBLE} مرحلة)` : `عرض الكل (${regularStages.length} مرحلة)`}
              </button>
            )}
          </div>
        )}

        {canEdit && (
          <div className="flex gap-1.5 mt-2">
            <button
              onClick={() => setIsEditing(true)}
              className="flex-1 flex items-center justify-center gap-1.5 py-1.5 text-[11px] font-bold text-slate-400 dark:text-slate-500 hover:text-primary dark:hover:text-primary hover:bg-primary/5 rounded-lg transition-colors border border-dashed border-slate-200 dark:border-slate-700"
            >
              <Edit2 className="w-3 h-3" /> تعديل المراحل
            </button>
            {onUnifyClick && (
              <button
                type="button"
                onClick={onUnifyClick}
                className="flex-1 flex items-center justify-center gap-1.5 py-1.5 text-[11px] font-bold text-slate-400 dark:text-slate-500 hover:text-amber-500 dark:hover:text-amber-500 hover:bg-amber-500/5 rounded-lg transition-colors border border-dashed border-slate-200 dark:border-slate-700"
              >
                <Layers className="w-3.5 h-3.5 text-amber-500" /> توحيد المراحل
              </button>
            )}
          </div>
        )}
      </div>
    );
  }

  // EDIT MODE
  const editRegular = sorted.filter(s => !s.isContinuous);
  const editContinuous = sorted.filter(s => s.isContinuous);

  function renderEditItem(stage: Stage, idx: number, isContinuousSection: boolean) {
    const contSortedList = isContinuousSection ? editContinuous : editRegular;  
    return (
      <div key={stage.id} className={`rounded-lg border p-2 ${isContinuousSection ? "border-amber-200 dark:border-amber-800/40 bg-amber-50/40 dark:bg-amber-900/10" : stage.isCurrent ? "border-primary/30 bg-primary/5" : "border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50"}`}>
          {editingId === stage.id ? (
            <div className="space-y-2">
              <input value={editName} onChange={e => setEditName(e.target.value)} placeholder="اسم المرحلة" autoFocus
                className="w-full text-xs bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded-lg px-3 py-1.5 outline-none focus:ring-2 focus:ring-primary/30 text-slate-800 dark:text-slate-100" />
              <input value={editDesc} onChange={e => setEditDesc(e.target.value)} placeholder="وصف (اختياري)"
                className="w-full text-xs bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded-lg px-3 py-1.5 outline-none focus:ring-2 focus:ring-primary/30 text-slate-800 dark:text-slate-100" />
              {/* خيار الأيام أو التواريخ */}
              <div className="rounded-lg bg-slate-50 dark:bg-slate-800/60 border border-slate-200 dark:border-slate-600 p-2 space-y-2">
                <div className="flex items-center gap-2">
                  <input
                    type="number" min="1" value={editDays}
                    onChange={e => {
                      setEditDays(e.target.value);
                      if (e.target.value) { setEditStart(""); setEditEnd(""); }
                    }}
                    placeholder="عدد الأيام"
                    className="w-24 text-xs bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg px-2 py-1.5 outline-none focus:ring-2 focus:ring-primary/30"
                  />
                  <label className="flex items-center gap-1.5 cursor-pointer text-xs text-slate-600 dark:text-slate-300">
                    <input type="checkbox" checked={editWorkDaysOnly} onChange={e => setEditWorkDaysOnly(e.target.checked)} className="w-3 h-3 accent-primary" />
                    أيام عمل فقط
                  </label>
                  {editDays && (
                    <span className="text-[10px] text-primary font-medium">
                      {(() => {
                        const idx = sorted.findIndex(s => s.id === editingId);
                        const prevEnd = idx > 0 ? sorted[idx - 1].endDate : null;
                        const calc = calcDatesFromDays(parseInt(editDays) || 1, editWorkDaysOnly, prevEnd);
                        return `${calc.start} ← ${calc.end}`;
                      })()}
                    </span>
                  )}
                </div>
                <div className="text-[10px] text-slate-400 text-center">— أو حدد التواريخ يدوياً —</div>
                <div className="flex gap-2">
                  <input type="date" value={editStart} onChange={e => { setEditStart(e.target.value); setEditDays(""); }}
                    className="flex-1 text-xs bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded-lg px-2 py-1.5 outline-none [color-scheme:light] dark:[color-scheme:dark]" />
                  <input type="date" value={editEnd} onChange={e => { setEditEnd(e.target.value); setEditDays(""); }}
                    className="flex-1 text-xs bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded-lg px-2 py-1.5 outline-none [color-scheme:light] dark:[color-scheme:dark]" />
                </div>
              </div>
              <label className="flex items-center gap-2 cursor-pointer text-xs text-slate-600 dark:text-slate-300">
                <input type="checkbox" checked={editIsContinuous} onChange={e => setEditIsContinuous(e.target.checked)} className="w-3.5 h-3.5 accent-amber-500" />
                <span>مرحلة دائمة (تعمل بالتوازي مع المراحل الأخرى)</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer text-xs text-slate-600 dark:text-slate-300">
                <input type="checkbox" checked={editIsComingSoon} onChange={e => setEditIsComingSoon(e.target.checked)} className="w-3.5 h-3.5 accent-purple-500" />
                <span>المرحلة قريباً (Coming Soon)</span>
              </label>
              <div className="flex gap-2">
                <button onClick={() => handleUpdate(stage.id)} disabled={isPending || !editName.trim()}
                  className="flex-1 py-1.5 text-xs font-bold text-white bg-primary hover:bg-primary/90 rounded-lg flex items-center justify-center gap-1 disabled:opacity-60">
                  {isPending ? <Loader2 className="w-3 h-3 animate-spin" /> : <Save className="w-3 h-3" />} حفظ
                </button>
                <button onClick={() => setEditingId(null)} className="px-3 py-1.5 text-xs font-bold text-slate-500 bg-slate-100 dark:bg-slate-700 hover:bg-slate-200 dark:hover:bg-slate-600 rounded-lg transition-colors">إلغاء</button>
              </div>
            </div>
          ) : (
            <div className="flex items-center gap-2">
              {/* Reorder */}
              <div className="flex flex-col gap-0.5 shrink-0">
                <button onClick={() => handleMove(idx, "up")} disabled={idx === 0 || isPending}
                  className="p-0.5 text-slate-300 hover:text-slate-600 disabled:opacity-20"><ArrowUp className="w-3 h-3" /></button>
                <button onClick={() => handleMove(idx, "down")} disabled={idx === contSortedList.length - 1 || isPending}
                  className="p-0.5 text-slate-300 hover:text-slate-600 disabled:opacity-20"><ArrowDown className="w-3 h-3" /></button>
              </div>
              {/* Badge */}
              <div className={`w-5 h-5 rounded-md flex items-center justify-center text-[10px] font-bold shrink-0 border ${
                isContinuousSection
                  ? "border-amber-400 bg-amber-400 text-white"
                  : stage.isCurrent
                    ? "border-primary bg-primary text-white rounded-full"
                    : "border-slate-300 dark:border-slate-600 text-slate-400 rounded-full"
              }`}>{isContinuousSection ? "∞" : idx + 1}</div>
              {/* Name */}
              <div className="flex-1 min-w-0">
                <div className={`text-xs font-semibold truncate flex items-center gap-1 ${isContinuousSection ? "text-amber-700 dark:text-amber-300" : stage.isCurrent ? "text-primary" : "text-slate-700 dark:text-slate-300"}`}>
                  {stage.name}
                  {stage.isComingSoon && <span className="text-[9px] bg-purple-500 text-white px-1.5 py-0.5 rounded-full font-bold">قريباً</span>}
                </div>
                {(stage.startDate || stage.endDate) && (
                  <div className="text-[10px] text-slate-400" dir="ltr">{fmtDate(stage.startDate)}{stage.startDate && stage.endDate ? "—" : ""}{fmtDate(stage.endDate)}</div>
                )}
              </div>
              {/* Actions */}
              <div className="flex items-center gap-1 shrink-0">
                <button onClick={() => handleToggleCurrent(stage.id)} disabled={isPending}
                  className={`text-[10px] px-1.5 py-0.5 border rounded transition-colors ${
                    isContinuousSection
                      ? stage.isCurrent
                        ? "bg-emerald-50 dark:bg-emerald-900/20 border-emerald-300 text-emerald-600 hover:bg-red-50 hover:border-red-300 hover:text-red-500"
                        : "bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-600 text-slate-500 hover:text-emerald-600 hover:border-emerald-300"
                      : stage.isCurrent
                        ? "bg-primary/10 border-primary/30 text-primary hover:bg-red-50 hover:border-red-300 hover:text-red-500"
                        : "bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-600 text-slate-500 hover:text-primary hover:border-primary/30"
                  }`}>
                  {isContinuousSection ? (stage.isCurrent ? "تعمل الآن ✓" : "تفعيل") : (stage.isCurrent ? "إلغاء الحالية" : "تعيين حالية")}
                </button>
                <button onClick={() => openEdit(stage)} disabled={isPending}
                  className="p-1 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded">
                  <Edit2 className="w-3 h-3" />
                </button>
                <button onClick={() => handleDelete(stage.id)} disabled={isPending}
                  className="p-1 text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded">
                  <Trash2 className="w-3 h-3" />
                </button>
              </div>
            </div>
          )}
        </div>
    );
  }

  return (
    <div className="mt-2 space-y-2">
      <div className="flex items-center justify-between mb-1">
        <span className="text-xs font-bold text-slate-600 dark:text-slate-300">تعديل المراحل</span>
        <button onClick={() => { setIsEditing(false); setEditingId(null); setIsAdding(false); }}
          className="text-xs text-slate-400 hover:text-slate-600 flex items-center gap-1 px-2 py-1 rounded hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
          <X className="w-3 h-3" /> إغلاق
        </button>
      </div>

      {/* المراحل المرقمة */}
      {editRegular.length > 0 && (
        <div className="space-y-1.5">
          <div className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wide px-1">المراحل المرحلية</div>
          {editRegular.map((stage, idx) => renderEditItem(stage, idx, false))}
        </div>
      )}

      {/* المراحل الدائمة — قسم مستقل */}
      {editContinuous.length > 0 && (
        <div className="space-y-1.5 pt-2 border-t border-dashed border-amber-200 dark:border-amber-800/40">
          <div className="text-[10px] font-bold text-amber-500 dark:text-amber-400 uppercase tracking-wide px-1">المهام الدائمة والمستمرة</div>
          {editContinuous.map((stage, idx) => renderEditItem(stage, idx, true))}
        </div>
      )}

      {/* Add stage */}
      {isAdding ? (
        <div className="rounded-lg border-2 border-primary border-dashed p-2 space-y-2">
          <input value={newName} onChange={e => setNewName(e.target.value)} placeholder="اسم المرحلة الجديدة" autoFocus
            className="w-full text-xs bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded-lg px-3 py-1.5 outline-none focus:ring-2 focus:ring-primary/30 text-slate-800 dark:text-slate-100" />
          <input value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="وصف (اختياري)"
            className="w-full text-xs bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded-lg px-3 py-1.5 outline-none focus:ring-2 focus:ring-primary/30 text-slate-800 dark:text-slate-100" />
          {/* خيار الأيام أو التواريخ */}
          <div className="rounded-lg bg-slate-50 dark:bg-slate-800/60 border border-slate-200 dark:border-slate-600 p-2 space-y-2">
            <div className="flex items-center gap-2">
              <input
                type="number" min="1" value={newDays}
                onChange={e => { setNewDays(e.target.value); if (e.target.value) { setNewStart(""); setNewEnd(""); } }}
                placeholder="عدد الأيام"
                className="w-24 text-xs bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg px-2 py-1.5 outline-none focus:ring-2 focus:ring-primary/30"
              />
              <label className="flex items-center gap-1.5 cursor-pointer text-xs text-slate-600 dark:text-slate-300">
                <input type="checkbox" checked={newWorkDaysOnly} onChange={e => setNewWorkDaysOnly(e.target.checked)} className="w-3 h-3 accent-primary" />
                أيام عمل فقط
              </label>
              {newDays && (
                <span className="text-[10px] text-primary font-medium">
                  {(() => {
                    const regularSorted = sorted.filter(s => !s.isContinuous);
                    const prevEnd = regularSorted.length > 0 ? regularSorted[regularSorted.length - 1].endDate : null;
                    const calc = calcDatesFromDays(parseInt(newDays) || 1, newWorkDaysOnly, prevEnd);
                    return `${calc.start} ← ${calc.end}`;
                  })()}
                </span>
              )}
            </div>
            <div className="text-[10px] text-slate-400 text-center">— أو حدد التواريخ يدوياً —</div>
            <div className="flex gap-2">
              <input type="date" value={newStart} onChange={e => { setNewStart(e.target.value); setNewDays(""); }}
                className="flex-1 text-xs bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded-lg px-2 py-1.5 outline-none [color-scheme:light] dark:[color-scheme:dark]" />
              <input type="date" value={newEnd} onChange={e => { setNewEnd(e.target.value); setNewDays(""); }}
                className="flex-1 text-xs bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded-lg px-2 py-1.5 outline-none [color-scheme:light] dark:[color-scheme:dark]" />
            </div>
          </div>
          <label className="flex items-center gap-2 cursor-pointer text-xs text-slate-600 dark:text-slate-300">
            <input type="checkbox" checked={newIsContinuous} onChange={e => setNewIsContinuous(e.target.checked)} className="w-3.5 h-3.5 accent-amber-500" />
            <span>مرحلة دائمة (تعمل بالتوازي مع المراحل الأخرى)</span>
          </label>
          <div className="flex gap-2">
            <button onClick={handleAdd} disabled={isPending || !newName.trim()}
              className="flex-1 py-1.5 text-xs font-bold text-white bg-primary hover:bg-primary/90 rounded-lg flex items-center justify-center gap-1 disabled:opacity-60">
              {isPending ? <Loader2 className="w-3 h-3 animate-spin" /> : <Plus className="w-3 h-3" />} إضافة
            </button>
            <button onClick={() => setIsAdding(false)} className="px-3 py-1.5 text-xs font-bold text-slate-500 bg-slate-100 dark:bg-slate-700 hover:bg-slate-200 dark:hover:bg-slate-600 rounded-lg transition-colors">إلغاء</button>
          </div>
        </div>
      ) : (
        <button onClick={() => setIsAdding(true)}
          className="w-full flex items-center justify-center gap-1.5 py-1.5 text-xs font-bold text-primary hover:bg-primary/5 rounded-lg border border-dashed border-primary/30 transition-colors">
          <Plus className="w-3 h-3" /> إضافة مرحلة
        </button>
      )}
    </div>
  );
}

// ── Charity Card ────────────────────────────────────────────────────
function CharityCard({
  charity, stages, dept, serviceId, canEdit, onUnifyClick, onLogoClick, charityLogoUrl,
}: {
  charity: Charity & { logoUrl?: string | null };
  stages: Stage[];
  dept: DeptKey;
  serviceId: string;
  canEdit: boolean;
  onUnifyClick?: () => void;
  onLogoClick?: () => void;
  charityLogoUrl?: string | null;
}) {
  const [open, setOpen] = useState(false);
  const sorted = [...stages].sort((a, b) => a.order - b.order);
  const regularSorted = sorted.filter(s => !s.isContinuous);
  // آخر مرحلة حالية
  const lastCurrentIdx = regularSorted.reduce((last, s, i) => s.isCurrent ? i : last, -1);
  const currentStage = lastCurrentIdx >= 0 ? regularSorted[lastCurrentIdx] : null;
  const completedCount = lastCurrentIdx >= 0 ? lastCurrentIdx : 0;
  const pct = regularSorted.length > 0 ? Math.round(((completedCount + (currentStage ? 0.5 : 0)) / regularSorted.length) * 100) : 0;
  const deptColor = DEPT_COLORS[dept] || "bg-slate-400";
  const deptLight = DEPT_LIGHT[dept] || "bg-slate-50 dark:bg-slate-800/50 border-slate-200 dark:border-slate-700";

  return (
    <div className={`rounded-xl border ${deptLight} overflow-hidden`}>
      <button className="w-full flex items-center justify-between gap-3 p-3 text-right" onClick={() => setOpen(o => !o)}>
        <div className="flex items-center gap-2 min-w-0">
          {/* Logo */}
          <div
            className="relative group/logo shrink-0"
            onClick={e => { e.stopPropagation(); onLogoClick?.(); }}
            title={canEdit ? "تغيير صورة الجمعية" : undefined}
          >
            {charityLogoUrl ? (
              <div className={`w-7 h-7 rounded-lg overflow-hidden border border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-900 flex items-center justify-center ${canEdit ? "cursor-pointer" : ""}`}>
                <img src={charityLogoUrl} alt={charity.name} className="w-full h-full object-contain p-0.5" />
              </div>
            ) : (
              <div className={`w-7 h-7 rounded-lg bg-primary/10 text-primary flex items-center justify-center text-xs font-bold border border-primary/20 ${canEdit ? "cursor-pointer" : ""}`}>
                {charity.name.charAt(0)}
              </div>
            )}
            {canEdit && (
              <div className="absolute inset-0 bg-black/40 rounded-lg flex items-center justify-center opacity-0 group-hover/logo:opacity-100 transition-opacity cursor-pointer">
                <Edit2 className="w-3 h-3 text-white" />
              </div>
            )}
          </div>
          <div className={`w-2 h-2 rounded-full shrink-0 ${deptColor}`} />
          <span className="font-bold text-sm text-slate-800 dark:text-slate-200 truncate">{charity.name}</span>
          {currentStage && <span className="text-xs text-slate-500 dark:text-slate-400 truncate hidden sm:inline">— {currentStage.name}</span>}
        </div>
        <div className="flex items-center gap-3 shrink-0">
          <div className="flex items-center gap-1.5">
            <div className="w-20 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
              <div className="h-full bg-primary rounded-full transition-all" style={{ width: `${pct}%` }} />
            </div>
            <span className="text-[11px] font-bold text-slate-500 dark:text-slate-400 w-7">{pct}%</span>
          </div>
          {open ? <ChevronDown className="w-4 h-4 text-slate-400" /> : <ChevronRight className="w-4 h-4 text-slate-400" />}
        </div>
      </button>
      {open && (
        <div className="px-3 pb-3 border-t border-slate-200/50 dark:border-slate-700/50">
          <InlineTimeline
            key={`${charity.id}-${dept}-${serviceId}`}
            stages={stages}
            charityId={charity.id}
            serviceId={serviceId}
            dept={dept}
            canEdit={canEdit}
            onUnifyClick={onUnifyClick}
          />
        </div>
      )}
    </div>
  );
}

// ── Print helper ────────────────────────────────────────────────────
function buildPrintHtml(deptKey: string, deptLabel: string, selectedCharities: Charity[], stagesData: Record<string, any[]>, svcName?: string): string {
  const isGeneric = deptKey.startsWith("SVC:");
  const svcId = isGeneric ? deptKey.replace("SVC:", "") : null;

  const CSS = `
    @page{size:A4;margin:18mm}
    body{font-family:Arial,sans-serif;font-size:11pt;color:#1e293b;direction:rtl;margin:0}
    h1{font-size:17pt;font-weight:bold;border-bottom:3px solid #0f766e;padding-bottom:8px;margin-bottom:4px}
    .print-date{color:#64748b;font-size:9pt;margin-bottom:20px}
    .charity-block{margin-bottom:36px;page-break-inside:avoid}
    .charity-name{font-size:14pt;font-weight:bold;background:#f0fdfa;padding:7px 12px;border-radius:6px;border-right:4px solid #0f766e;margin-bottom:12px}
    .section-label{font-size:11pt;font-weight:bold;color:#0f766e;margin:14px 0 6px;border-bottom:1px solid #e2e8f0;padding-bottom:3px}
    table{width:100%;border-collapse:collapse;font-size:9pt;margin-bottom:6px}
    th{background:#0f766e;color:#fff;padding:5px 8px;text-align:right}
    td{padding:4px 8px;border-bottom:1px solid #e2e8f0;vertical-align:top}
    tr:nth-child(even) td{background:#f8fafc}
    .steps-cell{font-size:8.5pt;color:#334155}
    .step-row{display:flex;align-items:flex-start;gap:5px;margin-bottom:3px}
    .step-check{width:11px;height:11px;border:1.5px solid #94a3b8;border-radius:2px;flex-shrink:0;margin-top:1px;display:inline-flex;align-items:center;justify-content:center}
    .step-check.done{background:#0f766e;border-color:#0f766e}
    .step-check.done::after{content:"✓";color:#fff;font-size:7pt;line-height:1}
    .step-name{line-height:1.4}
    .b-cur{background:#fff;color:#0f766e;font-size:8pt;padding:0.5px 6px;border-radius:10px;border:1.5px solid #0f766e}
    .b-done{background:#0f766e;color:#fff;font-size:8pt;padding:1px 6px;border-radius:10px}
    .b-cont-active{background:#0f766e;color:#fff;font-size:8pt;padding:1px 6px;border-radius:10px}
    .b-cont-soon{background:#ca8a04;color:#fff;font-size:8pt;padding:1px 6px;border-radius:10px}
  `;

  function renderStepsHtml(steps: StageStep[]): string {
    if (!steps.length) return "—";
    return `<div class="steps-cell">${steps.map(st =>
      `<div class="step-row"><span class="step-check ${st.isDone ? "done" : ""}"></span><span class="step-name">${st.name}</span></div>`
    ).join("")}</div>`;
  }

  function renderStagesTable(stgs: Stage[], numbered: boolean): string {
    if (!stgs.length) return "";
    if (!stgs.length) return "";
    const ci = numbered ? stgs.findIndex(s => s.isCurrent) : -1;
    let rows = "";
    stgs.forEach((s, i) => {
      const done = numbered && ci !== -1 && i < ci;
      const cur = s.isCurrent;
      const dates = [s.startDate ? fmtDate(s.startDate) : "", s.endDate ? fmtDate(s.endDate) : ""].filter(Boolean).join(" — ");
      const steps: StageStep[] = (s as any).steps || [];

      let badge: string;
      if (!numbered) {
        // مرحلة دائمة
        badge = cur ? `<span class="b-cont-active">تعمل الآن</span>` : `<span class="b-cont-soon">قريباً</span>`;
      } else {
        badge = cur ? `<span class="b-cur">الحالية</span>` : done ? `<span class="b-done">مكتملة</span>` : "—";
      }

      const numCell = numbered ? `<td style="text-align:center;font-weight:bold;width:30px">${i + 1}</td>` : "";
      rows += `<tr>${numCell}<td style="font-weight:${cur ? "bold" : "normal"}">${s.name}</td><td style="color:#475569;max-width:160px">${s.description || "—"}</td><td dir="ltr" style="font-size:8.5pt;color:#475569;white-space:nowrap">${dates || "—"}</td><td>${renderStepsHtml(steps)}</td><td>${badge}</td></tr>`;
    });
    const numHeader = numbered ? "<th style='width:30px'>#</th>" : "";
    return `<table><thead><tr>${numHeader}<th>المرحلة</th><th>الوصف</th><th>الفترة</th><th>الخطوات</th><th>الحالة</th></tr></thead><tbody>${rows}</tbody></table>`;
  }

  let body = "";
  for (const charity of selectedCharities) {
    let allStgs: Stage[] = [];
    if (!isGeneric) {
      allStgs = ((stagesData[deptKey] || []) as Stage[]).filter(s => s.charityId === charity.id).sort((a, b) => a.order - b.order);
    } else {
      // البحث بالاسم أولاً (لأن كل جمعية لها id مختلف لنفس الخدمة)
      const svc = ((stagesData["SERVICES"] || []) as ServiceWithStages[]).find(s =>
        s.charityId === charity.id && (svcName ? s.name === svcName : s.id === svcId)
      );
      allStgs = (svc?.stages || []).sort((a: Stage, b: Stage) => a.order - b.order);
    }
    if (!allStgs.length) continue;

    const continuous = allStgs.filter(s => s.isContinuous);
    const regular = allStgs.filter(s => !s.isContinuous);

    let charityHtml = `<div class="charity-block"><div class="charity-name">${charity.name}</div>`;
    if (regular.length) {
      charityHtml += `<div class="section-label">المراحل المرحلية</div>${renderStagesTable(regular, true)}`;
    }
    if (continuous.length) {
      charityHtml += `<div class="section-label">المهام الدائمة والمستمرة</div>${renderStagesTable(continuous, false)}`;
    }
    charityHtml += `</div>`;
    body += charityHtml;
  }

  if (!body) body = `<p style="color:#94a3b8;text-align:center;margin-top:40px">لا توجد بيانات للجمعيات المحددة</p>`;

  return `<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8"/><title>خطة ${deptLabel}</title><style>${CSS}</style></head><body>
<h1>${deptLabel}</h1><p class="print-date">تاريخ الطباعة: ${new Date().toLocaleDateString("ar-SA")}</p>
${body}</body></html>`;
}

// ── Main Export ─────────────────────────────────────────────────────
export default function ServicesOverviewClient({
  charities, stagesData, isAdmin, editableTabs, editableServiceNames, canManageServices, role, deptLabels, allowedCharityIds,
}: {
  charities: Charity[];
  stagesData: Record<string, any[]>;
  isAdmin: boolean;
  editableTabs: Record<string, boolean>;
  /** الخدمات العامّة التي يعدّلها المستخدم. null = كلها (الإداري). */
  editableServiceNames: string[] | null;
  /** «إدارة الخدمات»: زرّ «+» للإضافة، وتعديل اسم الخدمة من تبويبها. */
  canManageServices: boolean;
  role: string;
  deptLabels: Record<string, string>;
  allowedCharityIds: string[] | null;
}) {
  const router = useRouter();

  // Print charity selection modal
  const [printModal, setPrintModal] = useState<{ deptKey: string; deptLabel: string; svcName?: string } | null>(null);
  const [printSelected, setPrintSelected] = useState<Set<string>>(new Set());

  function openPrintModal(deptKey: string, deptLabel: string, availableCharities: Charity[], svcName?: string) {
    setPrintSelected(new Set(availableCharities.map(c => c.id)));
    setPrintModal({ deptKey, deptLabel, svcName });
  }

  function executePrint() {
    if (!printModal) return;
    const selected = charities.filter(c => printSelected.has(c.id));
    const html = buildPrintHtml(printModal.deptKey, printModal.deptLabel, selected, stagesData, printModal.svcName);

    const w = window.open("", "_blank", "width=900,height=700");
    if (!w) {
      alert("الرجاء السماح بفتح النوافذ المنبثقة (Popups) للطباعة.");
      return;
    }
    w.document.open();
    w.document.write(html);
    w.document.close();
    setPrintModal(null);
    w.onload = () => w.print();
    // fallback in case onload doesn't fire reliably for document.write in some browsers
    setTimeout(() => { try { w.print(); } catch {} }, 300);
  }

  // Local logo state to avoid router.refresh() on logo update
  const [logoUrls, setLogoUrls] = useState<Record<string, string | null>>({});
  const getLogoUrl = (charity: Charity) => logoUrls[charity.id] !== undefined ? logoUrls[charity.id] : charity.logoUrl ?? null;

  // Service name editing
  const [editingServiceId, setEditingServiceId] = useState<string | null>(null);
  const [editingServiceName, setEditingServiceName] = useState("");
  const [serviceNames, setServiceNames] = useState<Record<string, string>>({});
  const [isServiceNamePending, startServiceNameTransition] = useTransition();
  /** رفض الخادم لاسمٍ عند التسمية («توجد خدمة بهذا الاسم»). */
  const [serviceNameError, setServiceNameError] = useState<string | null>(null);

  // إضافة خدمة من «الكل»
  const [showAddService, setShowAddService] = useState(false);
  const [newServiceName, setNewServiceName] = useState("");
  const [newServiceCharityIds, setNewServiceCharityIds] = useState<string[]>([]);
  const [addServiceError, setAddServiceError] = useState<string | null>(null);
  const [isAddingService, startAddService] = useTransition();

  // Builtin tab name editing (STRATEGY/GOVERNANCE/FINANCE)
  const [editingBuiltinTab, setEditingBuiltinTab] = useState<string | null>(null);
  const [editingBuiltinName, setEditingBuiltinName] = useState("");
  const [builtinNames, setBuiltinNames] = useState<Record<string, string>>({});
  const [isBuiltinNamePending, startBuiltinNameTransition] = useTransition();

  const handleSaveBuiltinName = (tabKey: string) => {
    if (!editingBuiltinName.trim()) return;
    startBuiltinNameTransition(async () => {
      setBuiltinNames(prev => ({ ...prev, [tabKey]: editingBuiltinName.trim() }));
      setEditingBuiltinTab(null);
      await updateTimelineDisplayName(tabKey, editingBuiltinName.trim());
    });
  };

  // Logo editing
  const [logoEditCharityId, setLogoEditCharityId] = useState<string | null>(null);
  const [logoPreview, setLogoPreview] = useState<string | null>(null);
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [logoError, setLogoError] = useState<string | null>(null);
  const [isLogoPending, startLogoTransition] = useTransition();
  const logoFileRef = useRef<HTMLInputElement>(null);

  const openLogoModal = (charityId: string, currentLogoUrl: string | null | undefined) => {
    setLogoEditCharityId(charityId);
    setLogoPreview(currentLogoUrl || null);
    setLogoFile(null);
    setLogoError(null);
  };

  const handleLogoFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 2 * 1024 * 1024) { setLogoError("حجم الملف يجب أن يكون أقل من 2 ميجابايت"); return; }
    setLogoPreview(URL.createObjectURL(file));
    setLogoFile(file);
    setLogoError(null);
  };

  // كانت تستدعي updateService على صفّ الخدمة في جمعيةٍ واحدة، فتقسم الخدمة إلى
  // اسمين (اسمٌ جديد في جمعية، والقديم في البقية) وتسقط منوحاتها — بلا فحص
  // تكرار. الآن تسمّي الخدمة في كل الجمعيات معاً، والخادم يرفض الاسم المأخوذ.
  const handleSaveServiceName = (svcId: string, dept: string | null, currentName: string) => {
    const name = editingServiceName.trim();
    if (!name) return;
    if (name === currentName) {
      setEditingServiceId(null);
      return;
    }
    setServiceNameError(null);
    startServiceNameTransition(async () => {
      const res = await renameServiceGlobally(currentName, name, dept);
      if (res?.error) {
        setServiceNameError(res.error);
        return;
      }
      setServiceNames(prev => ({ ...prev, [svcId]: name }));
      setEditingServiceId(null);
      router.refresh();
    });
  };

  const openAddService = () => {
    setNewServiceName("");
    // الجمعيات المعروضة في الصفحة — وهي لغير الإداري جمعياته المسنَدة.
    setNewServiceCharityIds(charities.map(c => c.id));
    setAddServiceError(null);
    setShowAddService(true);
  };

  const handleAddService = (e: { preventDefault: () => void }) => {
    e.preventDefault();
    const name = newServiceName.trim();
    if (!name) return;
    if (newServiceCharityIds.length === 0) {
      setAddServiceError("يرجى تحديد جمعية واحدة على الأقل");
      return;
    }
    setAddServiceError(null);
    startAddService(async () => {
      const res = await addServiceToCharities(name, null, newServiceCharityIds);
      if (res?.error) {
        setAddServiceError(res.error);
        return;
      }
      setShowAddService(false);
      router.refresh();
    });
  };

  const [showComingSoonModal, setShowComingSoonModal] = useState(false);

  const handleToggleComingSoonAll = (name: string, dept: string | null, isComingSoon: boolean) => {
    startServiceNameTransition(async () => {
      await toggleServiceComingSoon(name, dept, isComingSoon);
      router.refresh();
    });
  };

  const handleToggleComingSoonSingle = (serviceId: string, isComingSoon: boolean) => {
    startServiceNameTransition(async () => {
      await toggleServiceComingSoonSingle(serviceId, isComingSoon);
      router.refresh();
    });
  };

  const handleSaveLogo = (charityId: string) => {
    startLogoTransition(async () => {
      let finalUrl: string | null = logoPreview;
      if (logoFile) {
        try {
          const data = await uploadFile(logoFile, "charity_logo");
          finalUrl = data.url;
        } catch (err) {
          setLogoError(err instanceof Error ? err.message : "فشل رفع الصورة");
          return;
        }
      }
      await updateCharityLogo(charityId, finalUrl);
      setLogoUrls(prev => ({ ...prev, [charityId]: finalUrl }));
      setLogoEditCharityId(null);
      setLogoPreview(null);
      setLogoFile(null);
    });
  };

  const [unifyCharity, setUnifyCharity] = useState<{
    id: string;
    name: string;
    sourceTimelineType: string;
    sourceServiceId?: string;
    departmentLabel: string;
  } | null>(null);
  const [unifyTargetIds, setUnifyTargetIds] = useState<string[]>([]);
  const [isUnifyPending, startUnifyTransition] = useTransition();

  const handleUnifySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!unifyCharity) return;
    startUnifyTransition(async () => {
      try {
        await unifyCharityStagesAction(unifyCharity.id, unifyCharity.sourceTimelineType, unifyCharity.sourceServiceId, unifyTargetIds.length ? unifyTargetIds : undefined);
        setUnifyCharity(null);
        setUnifyTargetIds([]);
        router.refresh();
        // activeTab is label-based now — survives key changes after refresh automatically
      } catch (error: any) {
        console.error("Error unifying stages", error);
        alert(error.message || "حدث خطأ أثناء تعميم المراحل");
      }
    });
  };

  const builtinDepts = ["STRATEGY", "GOVERNANCE", "FINANCE"].filter(d => d in stagesData);
  const allServices: ServiceWithStages[] = (stagesData["SERVICES"] || []).filter((s: ServiceWithStages) => s.name?.trim());

  const uniqueServiceKeys = useMemo(() => {
    const seen = new Map<string, { name: string; dept: string | null; id: string; isComingSoon?: boolean }>();
    for (const svc of allServices) {
      // Group by name+dept so same service across charities shares one tab
      // But if name is empty, use id to avoid merging unrelated services
      const key = svc.name?.trim() ? `${svc.name}__${svc.department || ""}` : svc.id;
      if (!seen.has(key)) seen.set(key, { name: svc.name, dept: svc.department ?? null, id: svc.id, isComingSoon: (svc as any).isComingSoon });
    }
    return Array.from(seen.values());
  }, [allServices]);

  const tabs = [
    ...builtinDepts.map(d => ({ key: d, label: deptLabels[d] || d })),
    ...uniqueServiceKeys.map(s => ({ key: `SVC:${s.id}`, label: s.name })),
  ];

  // Store active tab label so it survives key changes after router.refresh (new services created by unify get new IDs)
  const [activeTabLabel, setActiveTabLabel] = useState(tabs[0]?.label || "");
  const activeTab = tabs.find(t => t.label === activeTabLabel)?.key || tabs[0]?.key || "";
  function setActiveTab(keyOrSetter: string | ((prev: string) => string)) {
    const key = typeof keyOrSetter === "function" ? keyOrSetter(activeTab) : keyOrSetter;
    const label = tabs.find(t => t.key === key)?.label || key;
    setActiveTabLabel(label);
  }
  const isGenericTab = activeTab.startsWith("SVC:");
  const genericSvcId = isGenericTab ? activeTab.replace("SVC:", "") : null;
  const activeLabel = tabs.find(t => t.key === activeTab)?.label || "";

  // Look up by id first, fall back to matching by label (handles id drift after re-render)
  const genericSvcInfo = genericSvcId
    ? (uniqueServiceKeys.find(s => s.id === genericSvcId) ?? uniqueServiceKeys.find(s => s.name === activeLabel) ?? null)
    : null;

  const handleOpenUnify = (charity: Charity) => {
    // Only called for builtin tabs (STRATEGY, GOVERNANCE, FINANCE)
    setUnifyCharity({
      id: charity.id,
      name: charity.name,
      sourceTimelineType: activeTab,
      sourceServiceId: undefined,
      departmentLabel: activeLabel
    });
  };

  // For CUSTOM service tabs — we know exactly which service to use
  const handleOpenUnifyCustom = (charity: Charity, knownServiceId: string) => {
    setUnifyCharity({
      id: charity.id,
      name: charity.name,
      sourceTimelineType: "CUSTOM",
      sourceServiceId: knownServiceId,
      departmentLabel: activeLabel
    });
  };

  // Extra charities picker (جمعيات غير موجودة في القائمة الحالية)
  const [showAddCharity, setShowAddCharity] = useState(false);
  const [showGantt, setShowGantt] = useState(false);

  const charitiesWithData = useMemo(() => {
    if (!isGenericTab) {
      return charities.filter(c => (stagesData[activeTab] || []).some((s: Stage) => s.charityId === c.id));
    }
    return charities.filter(c => allServices.some(svc => svc.name === genericSvcInfo?.name && svc.charityId === c.id));
  }, [activeTab, charities, stagesData, allServices, isGenericTab, genericSvcInfo]);

  // Charities that have NO data in this tab yet
  const charitiesWithoutData = useMemo(() => {
    const withIds = new Set(charitiesWithData.map(c => c.id));
    return charities.filter(c => !withIds.has(c.id));
  }, [charities, charitiesWithData]);

  // بعد useMemo لا قبله: قراءة genericSvcInfo.name قبلها تجعل مُترجِم React
  // يستنتج تبعيةً أدقّ من المُعلنة فيرفض الحفظ اليدوي.
  //
  // التبويب العام يُحكَم بالخدمة النشطة نفسها لا بمفتاحٍ واحد لكل الخدمات:
  // من مُنح «التقنية» يعدّل «التقنية» ويشاهد غيرها. وهي القاعدة ذاتها في صفحة
  // الجمعية، فلا تفترق الصفحتان مرّةً أخرى. والتبويبات المدمجة (الاستراتيجية
  // والحوكمة والمالية) باقية على صلاحياتها.
  const canEdit = isGenericTab
    ? editableServiceNames === null ||
      (!!genericSvcInfo && editableServiceNames.includes(genericSvcInfo.name))
    : editableTabs[activeTab] || false;

  // Extra charities manually added to view (empty timeline)
  const [extraCharityIds, setExtraCharityIds] = useState<string[]>([]);
  const extraCharities = charities.filter(c => extraCharityIds.includes(c.id));

  const allStages: Stage[] = !isGenericTab ? (stagesData[activeTab] || []) : [];
  const totalCharities = charitiesWithData.length;
  const doneCharities = charitiesWithData.filter(c => {
    if (isGenericTab) return allServices.some(svc => svc.name === genericSvcInfo?.name && svc.charityId === c.id && svc.stages.some(s => s.isCurrent));
    return allStages.filter((s: Stage) => s.charityId === c.id).some((s: Stage) => s.isCurrent);
  }).length;

  function getDept(): DeptKey {
    if (activeTab === "STRATEGY") return "STRATEGY";
    if (activeTab === "GOVERNANCE") return "GOVERNANCE";
    if (activeTab === "FINANCE") return "FINANCE";
    return "SERVICE";
  }

  return (
    <div className="space-y-5 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Header */}
      <div className="bg-white dark:bg-slate-800 rounded-2xl p-4 border border-slate-100 dark:border-slate-700 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 bg-primary/10 rounded-xl flex items-center justify-center text-primary shrink-0">
            <LayoutGrid className="w-4 h-4" />
          </div>
          <div>
            <h1 className="text-base font-bold text-slate-800 dark:text-slate-100">عرض الخدمات عبر الجمعيات</h1>
            <p className="text-xs text-slate-500 dark:text-slate-400">اختر قسماً لمشاهدة حالته في جميع الجمعيات دفعة واحدة</p>
          </div>
        </div>
      </div>

      {tabs.length > 0 && (
        <div className="bg-white dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700 shadow-sm overflow-hidden">
          {/* Tabs */}
          <div className="flex overflow-x-auto border-b border-slate-100 dark:border-slate-700 scrollbar-none">
            {tabs.map(tab => {
              const isSvc = tab.key.startsWith("SVC:");
              const isBuiltin = ["STRATEGY", "GOVERNANCE", "FINANCE"].includes(tab.key);
              const svcId = isSvc ? tab.key.replace("SVC:", "") : null;
              const svcInfo = svcId ? uniqueServiceKeys.find(s => s.id === svcId) : null;
              const displayName = isBuiltin
                ? (builtinNames[tab.key] || tab.label)
                : ((svcId && serviceNames[svcId]) || tab.label);
              const isEditingThis = svcId !== null && editingServiceId === svcId;
              const isEditingBuiltin = isBuiltin && editingBuiltinTab === tab.key;

              return (
                <div key={tab.key} className="relative flex items-center group/tab">
                  {isEditingThis ? (
                    <div className="flex items-center gap-1 px-2 py-2">
                      <input
                        autoFocus
                        value={editingServiceName}
                        onChange={e => setEditingServiceName(e.target.value)}
                        onKeyDown={e => {
                          if (e.key === "Enter") handleSaveServiceName(svcId!, svcInfo?.dept ?? null, displayName);
                          if (e.key === "Escape") setEditingServiceId(null);
                        }}
                        className="text-xs font-bold border border-primary/40 rounded px-2 py-1 outline-none focus:ring-1 focus:ring-primary/30 bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100 w-28"
                      />
                      <button onClick={() => handleSaveServiceName(svcId!, svcInfo?.dept ?? null, displayName)} disabled={isServiceNamePending}
                        className="p-1 text-primary hover:bg-primary/10 rounded">
                        {isServiceNamePending ? <Loader2 className="w-3 h-3 animate-spin" /> : <Save className="w-3 h-3" />}
                      </button>
                      <button onClick={() => setEditingServiceId(null)} className="p-1 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded">
                        <X className="w-3 h-3" />
                      </button>
                    </div>
                  ) : isEditingBuiltin ? (
                    <div className="flex items-center gap-1 px-2 py-2">
                      <input
                        autoFocus
                        value={editingBuiltinName}
                        onChange={e => setEditingBuiltinName(e.target.value)}
                        onKeyDown={e => {
                          if (e.key === "Enter") handleSaveBuiltinName(tab.key);
                          if (e.key === "Escape") setEditingBuiltinTab(null);
                        }}
                        className="text-xs font-bold border border-primary/40 rounded px-2 py-1 outline-none focus:ring-1 focus:ring-primary/30 bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100 w-28"
                      />
                      <button onClick={() => handleSaveBuiltinName(tab.key)} disabled={isBuiltinNamePending}
                        className="p-1 text-primary hover:bg-primary/10 rounded">
                        {isBuiltinNamePending ? <Loader2 className="w-3 h-3 animate-spin" /> : <Save className="w-3 h-3" />}
                      </button>
                      <button onClick={() => setEditingBuiltinTab(null)} className="p-1 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded">
                        <X className="w-3 h-3" />
                      </button>
                    </div>
                  ) : (
                    <>
                      <button onClick={() => { setActiveTab(tab.key); setExtraCharityIds([]); }}
                        className={`px-4 py-3 text-sm font-bold whitespace-nowrap transition-colors border-b-2 -mb-px ${
                          activeTab === tab.key ? "border-primary text-primary bg-primary/5" : "border-transparent text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200"
                        }`}>
                        {displayName}
                      </button>
                      {canManageServices && isSvc && (
                        <button
                          onClick={() => { setEditingServiceId(svcId!); setEditingServiceName(displayName); setServiceNameError(null); }}
                          className="absolute -top-0.5 left-0 opacity-0 group-hover/tab:opacity-100 transition-opacity p-0.5 text-slate-400 hover:text-primary"
                          title="تعديل اسم الخدمة"
                        >
                          <Edit2 className="w-2.5 h-2.5" />
                        </button>
                      )}
                      {isAdmin && isBuiltin && (
                        <button
                          onClick={() => { setEditingBuiltinTab(tab.key); setEditingBuiltinName(displayName); }}
                          className="absolute -top-0.5 left-0 opacity-0 group-hover/tab:opacity-100 transition-opacity p-0.5 text-slate-400 hover:text-primary"
                          title="تعديل اسم القسم"
                        >
                          <Edit2 className="w-2.5 h-2.5" />
                        </button>
                      )}
                    </>
                  )}
                </div>
              );
            })}
            {canManageServices && (
              <button
                onClick={openAddService}
                title="إضافة خدمة جديدة"
                aria-label="إضافة خدمة جديدة"
                className="px-3.5 py-3 shrink-0 flex items-center text-slate-400 hover:text-primary hover:bg-primary/5 border-b-2 border-transparent -mb-px transition-colors"
              >
                <Plus className="w-4 h-4" />
              </button>
            )}
          </div>

          {serviceNameError && (
            <div className="px-4 py-2 text-xs font-bold text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/20 border-b border-red-100 dark:border-red-900/30 flex items-center gap-1.5">
              <AlertCircle className="w-3.5 h-3.5 shrink-0" />
              {serviceNameError}
              <button onClick={() => setServiceNameError(null)} className="mr-auto p-0.5 text-red-400 hover:text-red-600" aria-label="إغلاق">
                <X className="w-3 h-3" />
              </button>
            </div>
          )}

          {/* Stats bar */}
          <div className="flex items-center justify-between gap-3 px-4 py-2.5 border-b border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-900/30">
            <div className="flex items-center gap-3 text-xs">
              <span className="text-slate-500 dark:text-slate-400">الجمعيات: <strong className="text-slate-800 dark:text-slate-200">{totalCharities}</strong></span>
              <span className="text-slate-500 dark:text-slate-400">نشطة: <strong className="text-emerald-600 dark:text-emerald-400">{doneCharities}</strong></span>
            </div>
            <div className="flex items-center gap-2">
              {canEdit && charitiesWithoutData.length > 0 && (
                <div className="relative">
                  <button
                    onClick={() => setShowAddCharity(v => !v)}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-600 dark:text-slate-300 rounded-lg transition-colors"
                  >
                    <Plus className="w-3.5 h-3.5" /> فتح خطة جمعية
                  </button>
                  {showAddCharity && (
                    <div className="absolute left-0 top-full mt-1 z-30 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-xl min-w-[180px] py-1 max-h-60 overflow-y-auto">
                      {charitiesWithoutData.map(c => (
                        <button
                          key={c.id}
                          onClick={() => {
                            setExtraCharityIds(prev => prev.includes(c.id) ? prev.filter(id => id !== c.id) : [...prev, c.id]);
                            setShowAddCharity(false);
                          }}
                          className="w-full text-right px-3 py-2 text-xs font-bold text-slate-700 dark:text-slate-200 hover:bg-primary/5 hover:text-primary transition-colors"
                        >
                          {c.name}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              )}
              <button
                onClick={() => setShowGantt(true)}
                className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-lg transition-colors">
                <GanttChartSquare className="w-3.5 h-3.5" /> غانت
              </button>
              <button onClick={() => openPrintModal(activeTab, activeLabel, charitiesWithData, isGenericTab ? genericSvcInfo?.name : undefined)}
                className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-lg transition-colors">
                <Printer className="w-3.5 h-3.5" /> طباعة
              </button>
            </div>
          </div>

          {/* Cards grid */}
          <div className="p-4">
            {charitiesWithData.length === 0 && extraCharities.length === 0 ? (
              <div className="text-center py-10 text-slate-400 dark:text-slate-500">
                <Briefcase className="w-9 h-9 mx-auto mb-2 opacity-40" />
                <p className="text-sm">لا توجد جمعيات لديها بيانات في هذا القسم</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-3">
                {charitiesWithData.map(charity => {
                  if (isGenericTab) {
                    const svcs = allServices.filter(svc => svc.name === genericSvcInfo?.name && svc.charityId === charity.id);
                    return svcs.map(svc => (
                      <CharityCard
                        key={svc.id}
                        charity={charity}
                        stages={svc.stages}
                        dept="SERVICE"
                        serviceId={svc.id}
                        canEdit={canEdit}
                        onUnifyClick={() => handleOpenUnifyCustom(charity, svc.id)}
                        charityLogoUrl={getLogoUrl(charity)}
                        onLogoClick={isAdmin ? () => openLogoModal(charity.id, getLogoUrl(charity)) : undefined}
                      />
                    ));
                  }
                  const stages = allStages.filter((s: Stage) => s.charityId === charity.id);
                  return (
                    <CharityCard
                      key={charity.id}
                      charity={charity}
                      stages={stages}
                      dept={getDept()}
                      serviceId=""
                      canEdit={canEdit}
                      onUnifyClick={() => handleOpenUnify(charity)}
                      charityLogoUrl={charity.logoUrl}
                      onLogoClick={isAdmin ? () => openLogoModal(charity.id, charity.logoUrl) : undefined}
                    />
                  );
                })}
                {/* Extra charities (empty timelines, canEdit only) */}
                {extraCharities.map(charity => {
                  return (
                    <CharityCard
                      key={charity.id}
                      charity={charity}
                      stages={[]}
                      dept={getDept()}
                      serviceId=""
                      canEdit={canEdit}
                      onUnifyClick={() => handleOpenUnify(charity)}
                      charityLogoUrl={charity.logoUrl}
                      onLogoClick={isAdmin ? () => openLogoModal(charity.id, charity.logoUrl) : undefined}
                    />
                  );
                })}
              </div>
            )}
          </div>

          {/* Bottom Action Bar for Coming Soon status */}
          {/* يتبع canEdit — منح الخدمة النشطة — لا isAdmin: من مُنح الخدمة
              يجعلها «قريباً» في جمعياته. وكان isAdmin هنا مدير النظام والمطوّر
              وحدهما، فلم يصلها حاملُ manage_services وإن قبله الخادم. */}
          {canEdit && isGenericTab && genericSvcInfo && (
            <div className="p-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-900/30 flex items-center justify-between flex-wrap gap-3 rounded-b-2xl">
              <div className="flex items-center gap-2.5">
                <div className={`p-2 rounded-xl ${genericSvcInfo.isComingSoon ? "bg-amber-500/10 text-amber-500" : "bg-slate-200/60 dark:bg-slate-700 text-slate-500"}`}>
                  <Clock className="w-5 h-5" />
                </div>
                <div>
                  <h4 className="font-bold text-sm text-slate-800 dark:text-slate-200">
                    حالة الخدمة (قريباً): {genericSvcInfo.isComingSoon ? <span className="text-amber-600 dark:text-amber-400">مُفعلة شمولياً (قريباً)</span> : <span className="text-slate-500">محددة / غير مُفعلة</span>}
                  </h4>
                  <p className="text-xs text-slate-500 dark:text-slate-400">
                    يمكنك تحديد وتعميم هذه الخدمة كـ "قريباً" لجميع الجمعيات أو تخصيصها لجمعيات محددة فقط.
                  </p>
                </div>
              </div>
              <button
                onClick={() => setShowComingSoonModal(true)}
                className="px-4 py-2 text-xs font-bold bg-amber-500 hover:bg-amber-600 text-white rounded-xl transition-all flex items-center gap-2 shadow-sm"
              >
                <Clock className="w-4 h-4" /> إدارة وضع (قريباً)
              </button>
            </div>
          )}
        </div>
      )}

      {/* Coming Soon Management Modal */}
      {showAddService && canManageServices && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4" dir="rtl">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowAddService(false)}></div>
          <form
            onSubmit={handleAddService}
            className="relative bg-white dark:bg-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700"
          >
            <div className="p-4 border-b border-slate-100 dark:border-slate-700">
              <h2 className="text-base font-bold text-slate-800 dark:text-slate-100">إضافة خدمة جديدة</h2>
            </div>
            <div className="p-4 space-y-4">
              <div>
                <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">اسم الخدمة</label>
                <input
                  autoFocus
                  type="text"
                  value={newServiceName}
                  onChange={e => { setNewServiceName(e.target.value); setAddServiceError(null); }}
                  aria-invalid={!!addServiceError}
                  placeholder="مثال: خدمة الإسناد الإداري..."
                  className={`w-full px-3 py-2 bg-slate-50 dark:bg-slate-900 border rounded-xl focus:ring-2 outline-none transition-all dark:text-white text-sm ${
                    addServiceError
                      ? "border-red-400 focus:ring-red-200 focus:border-red-400"
                      : "border-slate-200 dark:border-slate-700 focus:ring-primary focus:border-primary"
                  }`}
                />
                {addServiceError && (
                  <p className="mt-2 text-xs font-bold text-red-600 dark:text-red-400 flex items-center gap-1.5">
                    <AlertCircle className="w-3.5 h-3.5 shrink-0" />
                    {addServiceError}
                  </p>
                )}
              </div>
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-sm font-bold text-slate-700 dark:text-slate-300">
                    الجمعيات <span className="text-xs font-medium text-slate-400">({newServiceCharityIds.length} من {charities.length})</span>
                  </label>
                  <button
                    type="button"
                    onClick={() => setNewServiceCharityIds(newServiceCharityIds.length === charities.length ? [] : charities.map(c => c.id))}
                    className="text-[11px] font-bold text-primary hover:text-primary/80"
                  >
                    {newServiceCharityIds.length === charities.length ? "إلغاء الكل" : "تحديد الكل"}
                  </button>
                </div>
                <div className="max-h-48 overflow-y-auto rounded-xl border border-slate-200 dark:border-slate-700 divide-y divide-slate-100 dark:divide-slate-700/60">
                  {charities.map(c => {
                    const on = newServiceCharityIds.includes(c.id);
                    return (
                      <button
                        key={c.id}
                        type="button"
                        onClick={() => setNewServiceCharityIds(prev => on ? prev.filter(x => x !== c.id) : [...prev, c.id])}
                        className={`w-full flex items-center gap-3 px-3 py-2 text-right text-xs font-bold transition-colors ${
                          on ? "bg-primary/5 dark:bg-primary/10 text-primary" : "text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700/40"
                        }`}
                      >
                        <span className={`w-4 h-4 rounded border flex items-center justify-center shrink-0 ${
                          on ? "bg-primary border-primary text-white" : "border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800"
                        }`}>
                          {on && <Check className="w-3 h-3" />}
                        </span>
                        {c.name}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
            <div className="flex gap-3 p-4 border-t border-slate-100 dark:border-slate-700">
              <button
                type="submit"
                disabled={isAddingService || !newServiceName.trim()}
                className="flex-1 bg-primary hover:bg-primary/90 text-white py-2 rounded-xl font-bold transition-colors disabled:opacity-50 text-sm"
              >
                {isAddingService ? "جاري الحفظ..." : "إضافة"}
              </button>
              <button
                type="button"
                onClick={() => setShowAddService(false)}
                className="flex-1 bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 py-2 rounded-xl font-bold transition-colors text-sm"
              >
                إلغاء
              </button>
            </div>
          </form>
        </div>
      )}

      {showComingSoonModal && canEdit && isGenericTab && genericSvcInfo && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowComingSoonModal(false)}></div>
          <div className="relative bg-white dark:bg-slate-800 rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 border border-slate-200 dark:border-slate-700" dir="rtl">
            <div className="p-5 border-b border-slate-100 dark:border-slate-700 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-amber-500/10 text-amber-500 rounded-xl">
                  <Clock className="w-6 h-6" />
                </div>
                <div>
                  <h2 className="text-lg font-bold text-slate-800 dark:text-slate-100">
                    تحديد حالة (قريباً) - {genericSvcInfo.name}
                  </h2>
                  <p className="text-xs text-slate-500 dark:text-slate-400">
                    التحكم في ظهور كلمة "قريباً" في بطاقات الجمعيات لهذه الخدمة
                  </p>
                </div>
              </div>
              <button onClick={() => setShowComingSoonModal(false)} className="p-1.5 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-5 space-y-5 max-h-[70vh] overflow-y-auto">
              {/* Option 1: All Charities */}
              <div className="p-4 bg-slate-50 dark:bg-slate-900/50 rounded-xl border border-slate-200/80 dark:border-slate-700 space-y-3">
                <div className="flex items-center justify-between">
                  <span className="font-bold text-sm text-slate-800 dark:text-slate-200">{isAdmin ? "التحكم الشامل (لكل الجمعيات)" : "التحكم الشامل (لجمعياتك)"}</span>
                  <span className="text-xs px-2 py-0.5 bg-amber-500/10 text-amber-600 dark:text-amber-400 font-bold rounded-md">{isAdmin ? "كل الجمعيات" : "جمعياتك"}</span>
                </div>
                <p className="text-xs text-slate-500 dark:text-slate-400">
                  تطبيق أو إلغاء حالة "قريباً" على كافة الجمعيات التي تحتوي على هذه الخدمة بضغطة واحدة.
                </p>
                <div className="flex gap-2 pt-1">
                  <button
                    disabled={isServiceNamePending}
                    onClick={() => handleToggleComingSoonAll(genericSvcInfo.name, genericSvcInfo.dept, true)}
                    className="flex-1 py-2 px-3 text-xs font-bold bg-amber-500 hover:bg-amber-600 text-white rounded-lg transition-colors flex items-center justify-center gap-1.5"
                  >
                    {isServiceNamePending ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Clock className="w-3.5 h-3.5" />}
                    {isAdmin ? "تفعيل لجميع الجمعيات" : "تفعيل لجمعياتك"}
                  </button>
                  <button
                    disabled={isServiceNamePending}
                    onClick={() => handleToggleComingSoonAll(genericSvcInfo.name, genericSvcInfo.dept, false)}
                    className="flex-1 py-2 px-3 text-xs font-bold bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-lg transition-colors flex items-center justify-center gap-1.5"
                  >
                    {isServiceNamePending ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <X className="w-3.5 h-3.5" />}
                    {isAdmin ? "إلغاء من جميع الجمعيات" : "إلغاء من جمعياتك"}
                  </button>
                </div>
              </div>

              {/* Option 2: Specific Charity List */}
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <span className="font-bold text-sm text-slate-800 dark:text-slate-200">تخصيص لجمعية محددة</span>
                  <span className="text-xs text-slate-400 font-medium">العدد: {charitiesWithData.length}</span>
                </div>
                <div className="divide-y divide-slate-100 dark:divide-slate-700/60 border border-slate-200 dark:border-slate-700 rounded-xl overflow-hidden">
                  {charitiesWithData.map(charity => {
                    const svcs = allServices.filter(svc => svc.name === genericSvcInfo.name && svc.charityId === charity.id);
                    const targetSvc = svcs[0];
                    if (!targetSvc) return null;
                    const isComing = (targetSvc as any).isComingSoon;

                    return (
                      <div key={charity.id} className="p-3 flex items-center justify-between bg-white dark:bg-slate-800 hover:bg-slate-50 dark:hover:bg-slate-750 transition-colors">
                        <div className="flex items-center gap-2.5">
                          <div className="w-7 h-7 rounded-lg bg-primary/10 text-primary flex items-center justify-center text-xs font-bold">
                            {charity.name.charAt(0)}
                          </div>
                          <span className="font-bold text-xs text-slate-700 dark:text-slate-200">{charity.name}</span>
                        </div>

                        <button
                          disabled={isServiceNamePending}
                          onClick={() => handleToggleComingSoonSingle(targetSvc.id, !isComing)}
                          className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-colors flex items-center gap-1.5 ${
                            isComing
                              ? "bg-amber-500/15 text-amber-600 dark:text-amber-400 hover:bg-amber-500/25 border border-amber-500/30"
                              : "bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-600"
                          }`}
                        >
                          <Clock className="w-3.5 h-3.5" />
                          {isComing ? "قريباً (مُفعل - اضغط للإلغاء)" : "تعيين كـ قريباً"}
                        </button>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>

            <div className="p-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50 flex justify-end">
              <button
                onClick={() => setShowComingSoonModal(false)}
                className="px-4 py-2 text-xs font-bold bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-lg transition-colors"
              >
                إغلاق
              </button>
            </div>
          </div>
        </div>
      )}

      {tabs.length === 0 && (
        <div className="bg-white dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700 p-12 text-center text-slate-400 dark:text-slate-500">
          لا توجد خدمات متاحة لحسابك حالياً
        </div>
      )}

      {/* Unify Stages Modal */}
      {unifyCharity && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setUnifyCharity(null)}></div>
          <div className="relative bg-white dark:bg-slate-800 rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 border border-slate-200 dark:border-slate-700" dir="rtl">
            <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex items-center gap-3">
              <div className="p-2 bg-amber-50 dark:bg-amber-950/30 text-amber-500 rounded-lg">
                <AlertTriangle className="w-6 h-6" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100">
                  تعميم مراحل {unifyCharity.departmentLabel}
                </h2>
                {unifyCharity.sourceTimelineType === "CUSTOM" && !unifyCharity.sourceServiceId && (
                  <p className="text-xs text-red-500 font-bold mt-1">هذه الجمعية ليس لديها خدمة "{unifyCharity.departmentLabel}" بعد — لا يمكن التعميم منها</p>
                )}
                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
                  نسخ مراحل قسم "{unifyCharity.departmentLabel}" من جمعية {unifyCharity.name} وتعميمها على كافة الجمعيات الأخرى
                </p>
              </div>
            </div>
            <form onSubmit={handleUnifySubmit} className="p-6 space-y-5">
              {/* Target charities selector */}
              {(() => {
                const otherCharities = charities.filter(c =>
                  c.id !== unifyCharity.id &&
                  (allowedCharityIds === null || allowedCharityIds.includes(c.id))
                );
                const allSelected = unifyTargetIds.length === otherCharities.length;
                return (
                  <div>
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-sm font-bold text-slate-700 dark:text-slate-200">الجمعيات المستهدفة</span>
                      <button
                        type="button"
                        onClick={() => setUnifyTargetIds(allSelected ? [] : otherCharities.map(c => c.id))}
                        className="text-xs font-bold text-primary hover:underline"
                      >
                        {allSelected ? "إلغاء تحديد الكل" : "تحديد الكل"}
                      </button>
                    </div>
                    <div className="border border-slate-200 dark:border-slate-600 rounded-xl max-h-44 overflow-y-auto divide-y divide-slate-100 dark:divide-slate-700">
                      {otherCharities.map(c => {
                        const checked = unifyTargetIds.includes(c.id);
                        return (
                          <label key={c.id} className="flex items-center gap-3 px-3 py-2.5 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                            <input
                              type="checkbox"
                              checked={checked}
                              onChange={() => setUnifyTargetIds(prev => checked ? prev.filter(id => id !== c.id) : [...prev, c.id])}
                              className="w-4 h-4 rounded accent-primary"
                            />
                            <span className="text-sm text-slate-700 dark:text-slate-200">{c.name}</span>
                          </label>
                        );
                      })}
                    </div>
                    {unifyTargetIds.length === 0 && (
                      <p className="text-xs text-amber-600 dark:text-amber-400 mt-1.5 font-bold">حدد جمعية واحدة على الأقل</p>
                    )}
                  </div>
                );
              })()}

              {/* Warning box */}
              <div className="p-4 bg-red-50 dark:bg-red-950/20 border border-red-100 dark:border-red-900/30 rounded-xl flex gap-3">
                <AlertCircle className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
                <p className="text-xs text-red-700/90 dark:text-red-300/80 leading-relaxed">
                  سيتم <strong>حذف المراحل الحالية</strong> للجمعيات المحددة واستبدالها بمراحل جمعية <strong>{unifyCharity.name}</strong>. هذا الإجراء غير قابل للتراجع.
                </p>
              </div>

              <div className="flex gap-3 pt-2 border-t border-slate-100 dark:border-slate-700">
                <button
                  type="submit"
                  disabled={isUnifyPending || unifyTargetIds.length === 0 || (unifyCharity.sourceTimelineType === "CUSTOM" && !unifyCharity.sourceServiceId)}
                  className="flex-1 bg-red-600 hover:bg-red-700 dark:bg-red-700 dark:hover:bg-red-600 text-white py-3 rounded-xl font-bold transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  {isUnifyPending ? "جاري التعميم..." : `تعميم على ${unifyTargetIds.length} جمعية`}
                </button>
                <button
                  type="button"
                  onClick={() => { setUnifyCharity(null); setUnifyTargetIds([]); }}
                  disabled={isUnifyPending}
                  className="flex-1 bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 py-3 rounded-xl font-bold transition-colors disabled:opacity-50"
                >
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Logo edit modal */}
      {logoEditCharityId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => !isLogoPending && setLogoEditCharityId(null)} />
          <div className="relative bg-white dark:bg-slate-800 rounded-2xl w-full max-w-sm shadow-2xl border border-slate-200 dark:border-slate-700 animate-in zoom-in-95 duration-200" dir="rtl">
            <div className="flex items-center justify-between px-5 py-4 border-b border-slate-100 dark:border-slate-700">
              <h3 className="text-sm font-bold text-slate-800 dark:text-slate-100">تغيير شعار الجمعية</h3>
              <button onClick={() => setLogoEditCharityId(null)} disabled={isLogoPending} className="p-1.5 text-slate-400 hover:text-slate-600 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">
                <X className="w-4 h-4" />
              </button>
            </div>
            <div className="p-5 space-y-4">
              {/* Preview */}
              <div className="flex justify-center">
                <button
                  type="button"
                  onClick={() => logoFileRef.current?.click()}
                  className="relative group w-24 h-24 rounded-2xl border-2 border-dashed border-slate-300 dark:border-slate-600 hover:border-primary dark:hover:border-primary bg-slate-50 dark:bg-slate-900 flex items-center justify-center overflow-hidden transition-colors cursor-pointer"
                >
                  {logoPreview ? (
                    <>
                      <img src={logoPreview} alt="preview" className="w-full h-full object-contain p-2" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                        <Edit2 className="w-5 h-5 text-white" />
                      </div>
                    </>
                  ) : (
                    <div className="text-center text-slate-400 dark:text-slate-500">
                      <Plus className="w-6 h-6 mx-auto mb-1" />
                      <span className="text-[10px] font-bold">اختر صورة</span>
                    </div>
                  )}
                </button>
              </div>

              <input
                ref={logoFileRef}
                type="file"
                accept="image/*"
                className="hidden"
                onChange={handleLogoFileChange}
              />

              <p className="text-center text-[11px] text-slate-400 dark:text-slate-500">
                PNG أو JPG أو SVG — الحد الأقصى 2 ميجابايت
              </p>

              {logoError && (
                <p className="text-xs text-red-600 dark:text-red-400 font-bold text-center">{logoError}</p>
              )}

              <div className="flex gap-2 pt-1">
                <button
                  onClick={() => handleSaveLogo(logoEditCharityId)}
                  disabled={isLogoPending}
                  className="flex-1 py-2 text-xs font-bold text-white bg-primary hover:bg-primary/90 rounded-lg flex items-center justify-center gap-1.5 disabled:opacity-60"
                >
                  {isLogoPending ? <Loader2 className="w-3 h-3 animate-spin" /> : <Save className="w-3 h-3" />}
                  {isLogoPending ? "جاري الرفع..." : "حفظ"}
                </button>
                {logoPreview && (
                  <button
                    onClick={() => { setLogoPreview(null); setLogoFile(null); }}
                    disabled={isLogoPending}
                    className="px-3 py-2 text-xs font-bold text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors disabled:opacity-50"
                  >
                    حذف
                  </button>
                )}
                <button onClick={() => setLogoEditCharityId(null)} disabled={isLogoPending} className="px-3 py-2 text-xs font-bold text-slate-500 bg-slate-100 dark:bg-slate-700 hover:bg-slate-200 rounded-lg transition-colors disabled:opacity-50">
                  إلغاء
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Backdrop for dropdown */}
      {showAddCharity && <div className="fixed inset-0 z-20" onClick={() => setShowAddCharity(false)} />}

      {/* Gantt Chart Modal */}
      {showGantt && (
        <GanttChart
          charities={charities}
          stagesData={stagesData}
          allServices={allServices}
          activeTab={activeTab}
          activeLabel={activeLabel}
          isGenericTab={isGenericTab}
          genericSvcName={genericSvcInfo?.name ?? null}
          deptColors={DEPT_COLORS}
          canEdit={canEdit}
          onClose={() => setShowGantt(false)}
        />
      )}

      {/* Print charity selection modal */}
      {printModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm" dir="rtl">
          <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-2xl w-full max-w-md">
            <div className="flex items-center justify-between px-5 py-4 border-b border-slate-100 dark:border-slate-800">
              <div className="flex items-center gap-2">
                <Printer className="w-4 h-4 text-primary" />
                <h2 className="font-bold text-slate-800 dark:text-slate-100 text-sm">اختر الجمعيات للطباعة</h2>
              </div>
              <button onClick={() => setPrintModal(null)} className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-400">
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="p-4 space-y-2 max-h-72 overflow-y-auto">
              {/* تحديد الكل / إلغاء الكل */}
              <div className="flex items-center justify-between mb-3 pb-2 border-b border-slate-100 dark:border-slate-800">
                <span className="text-xs text-slate-500 dark:text-slate-400">
                  {printSelected.size} من {charities.length} جمعية محددة
                </span>
                <div className="flex gap-2">
                  <button
                    onClick={() => setPrintSelected(new Set(charities.map(c => c.id)))}
                    className="text-[11px] font-bold text-primary hover:text-primary/80"
                  >
                    تحديد الكل
                  </button>
                  <span className="text-slate-300">|</span>
                  <button
                    onClick={() => setPrintSelected(new Set())}
                    className="text-[11px] font-bold text-slate-400 hover:text-slate-600"
                  >
                    إلغاء الكل
                  </button>
                </div>
              </div>

              {charities.map(c => (
                <label key={c.id} className="flex items-center gap-3 p-2.5 rounded-xl hover:bg-slate-50 dark:hover:bg-slate-800 cursor-pointer transition-colors">
                  <input
                    type="checkbox"
                    checked={printSelected.has(c.id)}
                    onChange={e => {
                      const next = new Set(printSelected);
                      if (e.target.checked) next.add(c.id);
                      else next.delete(c.id);
                      setPrintSelected(next);
                    }}
                    className="w-4 h-4 rounded accent-primary"
                  />
                  <span className="text-sm font-semibold text-slate-700 dark:text-slate-200">{c.name}</span>
                </label>
              ))}
            </div>

            <div className="flex items-center justify-end gap-2 px-5 py-4 border-t border-slate-100 dark:border-slate-800">
              <button onClick={() => setPrintModal(null)} className="px-4 py-2 text-sm text-slate-500 hover:text-slate-700 transition-colors">
                إلغاء
              </button>
              <button
                onClick={executePrint}
                disabled={printSelected.size === 0}
                className="flex items-center gap-2 px-5 py-2 bg-primary hover:bg-primary/90 disabled:opacity-40 text-white rounded-xl text-sm font-bold transition-colors"
              >
                <Printer className="w-4 h-4" />
                طباعة ({printSelected.size})
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
